 "content": "def transform(grid):
    """Draw full marker-aligned lines and recolor any 2-component they hit."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    rows = {r for r in range(h) if sum(grid[r][c] == 1 for c in range(w)) >= 2}
    cols = {c for c in range(w) if sum(grid[r][c] == 1 for r in range(h)) >= 2}

    # A line that reaches a colored object changes the whole connected object.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            hit = False
